#include <iostream>

class PointGraphic {
private:
    int x;
    int y;
    int color;
public:
    // Constructor with default values for all arguments
    PointGraphic(int xVal = 0, int yVal = 0, int colorVal = 15)
        : x(xVal), y(yVal), color(colorVal) {}

    void print() const {
        std::cout << x << " " << y << " " << color << "\n";
    }
};

int main() {
    // Invoking with 3 explicit arguments
    PointGraphic d1(200, 200, 10);

    // Invoking with all default arguments
    PointGraphic d2;

    // Reassigning with 2 explicit arguments (1 default)
    d2 = PointGraphic(300, 300);

    d1.print();
    d2.print();

    return 0;
}

#include <iostream>

class Fraction {
private:
    int numerator;
    int denominator;
public:
    // Parameterless constructor with default values
    Fraction(int num = 0, int den = 1) : numerator(num), denominator(den) {}

    // Overloaded stream operators for I/O
    friend std::ostream& operator<<(std::ostream& os, const Fraction& p) {
        os << p.numerator << "/" << p.denominator;
        return os;
    }

    friend std::istream& operator>>(std::istream& is, Fraction& p) {
        is >> p.numerator >> p.denominator;
        return is;
    }
};

int main() {
    // Original fraction initialized from simulated input
    Fraction d(3, 4);

    // Default copy constructor initializes 'u' as a memberwise copy of 'd'
    Fraction u(d);

    std::cout << "Fraction d = " << d << "\n";
    std::cout << "Fraction u = " << u << "\n";

    return 0;
}
